"""Finite plan model, not a Twenty runtime test. Run from any directory."""

import itertools
import json


# Hand-authored expected rows from decision-tables E/publish, P and C.
PUBLISH_EXPECTED = {
    (False, False, False): (False, True),
    (False, True, False): (False, False),
    (True, False, False): (False, False),
    (True, True, False): (False, False),
    (True, False, True): (True, False),
    (True, True, True): (True, False),
}
SEND_EXPECTED = {
    ('human', 'human'): True, ('human', 'assist'): True,
    ('human', 'auto'): False,
    ('ai', 'human'): False, ('ai', 'assist'): False, ('ai', 'auto'): True,
    ('workflow', 'human'): False, ('workflow', 'assist'): False,
    ('workflow', 'auto'): True,
    ('template', 'human'): True, ('template', 'assist'): True,
    ('template', 'auto'): True,
}
# Human auto admission must first perform takeover. This tests dispatch after
# admission, not the pre-takeover composer and not draft generation.
ACTIVE_HUMAN_EXPECTED = {
    'pending': True, 'dispatching': True, 'accepted': True,
    'outcome_unknown': True, 'sent': False, 'failed': False, 'cancelled': False,
}
OBSERVATIONS = ('ack', 'timeout', 'sent_proof', 'reject_proof',
                'cancel_request', 'cancel_proof')
LIFECYCLE_EXPECTED = {
    'dispatching': ('accepted', 'outcome_unknown', 'sent', 'failed',
                    'dispatching', 'cancelled'),
    'accepted': ('accepted', 'outcome_unknown', 'sent', 'failed',
                 'accepted', 'cancelled'),
    'outcome_unknown': ('accepted', 'outcome_unknown', 'sent', 'failed',
                        'outcome_unknown', 'cancelled'),
}


def publish(captured_governed, current_governed, pinned_target, mutant):
    native = not current_governed and not pinned_target
    if mutant != 'drop_captured_catalog':
        native = native and not captured_governed
    return pinned_target, native


def dispatch(sender, mode, closed, rights, route, epoch, scope, template, mutant):
    if closed or not rights or not route:
        return False
    if not scope and mutant != 'ignore_scope_edges':
        return False
    if sender == 'human':
        return mode != 'auto'
    if not epoch and mutant != 'ignore_automation_epoch':
        return False
    if sender == 'template':
        return template
    return mode == 'auto'


def transition(state, observation, mutant):
    if state in ('sent', 'failed', 'cancelled'):
        if (mutant == 'late_timeout_regresses_sent' and state == 'sent'
                and observation == 'timeout'):
            return 'outcome_unknown'
        return state
    if observation == 'cancel_request':
        return 'cancelled' if mutant == 'request_equals_cancel' else state
    if observation == 'timeout':
        return 'pending' if mutant == 'timeout_resends' else 'outcome_unknown'
    return {'ack': 'accepted', 'sent_proof': 'sent',
            'reject_proof': 'failed', 'cancel_proof': 'cancelled'}[observation]


def check(mutant=None):
    failures = []
    counts = {'publish': 0, 'dispatch': 0, 'human_mode_gate': 0, 'lifecycle': 0}

    def equal(group, case, actual, expected):
        counts[group] += 1
        if actual != expected:
            failures.append({'group': group, 'case': case,
                             'actual': actual, 'expected': expected})

    for case, expected in PUBLISH_EXPECTED.items():
        equal('publish', case, publish(*case, mutant), expected)

    # 12 hand-authored sender/mode rows × all 64 boolean guard combinations.
    for (sender, mode), mode_allowed in SEND_EXPECTED.items():
        for closed, rights, route, epoch, scope, template in itertools.product(
                (False, True), repeat=6):
            expected = mode_allowed
            denied_by_invariant = (closed or not rights or not route or not scope
                                   or (sender != 'human' and not epoch)
                                   or (sender == 'template' and not template))
            if denied_by_invariant:
                expected = False
            case = (sender, mode, closed, rights, route, epoch, scope, template)
            equal('dispatch', case, dispatch(*case, mutant), expected)

    for state, expected in ACTIVE_HUMAN_EXPECTED.items():
        outstanding = state not in ('sent', 'failed', 'cancelled')
        if mutant == 'accepted_not_outstanding' and state == 'accepted':
            outstanding = False
        equal('human_mode_gate', state, outstanding, expected)

    for state, outcomes in LIFECYCLE_EXPECTED.items():
        for observation, expected in zip(OBSERVATIONS, outcomes, strict=True):
            equal('lifecycle', (state, observation),
                  transition(state, observation, mutant), expected)
    for terminal in ('sent', 'failed', 'cancelled'):
        for observation in OBSERVATIONS:
            # Contradictory proof goes to reconciliation, never silent overwrite.
            equal('lifecycle', (terminal, observation),
                  transition(terminal, observation, mutant), terminal)
    return counts, failures


def main():
    counts, failures = check()
    if failures:
        raise AssertionError(failures)
    mutations = {}
    for mutant in ('drop_captured_catalog', 'ignore_scope_edges',
                   'ignore_automation_epoch', 'accepted_not_outstanding',
                   'late_timeout_regresses_sent', 'request_equals_cancel',
                   'timeout_resends'):
        _, caught = check(mutant)
        if not caught:
            raise AssertionError(f'Uncaught negative control: {mutant}')
        mutations[mutant] = {'caught': len(caught), 'witness': caught[0]}
    print(json.dumps({'scope': 'abstract plan only', 'cases': counts,
                      'total': sum(counts.values()), 'failures': 0,
                      'negative_controls': mutations,
                      'runtime_tests': False}, indent=2))


if __name__ == '__main__':
    main()

