          true,
          false,
          false,
          false
        ],
        "actual": true,
        "expected": false
      }
    },
    "ignore_automation_epoch": {
      "caught": 7,
      "witness": {
        "group": "dispatch",
        "case": [
          "ai",
          "auto",
          false,
          true,
          true,
          false,
          true,
          false
        ],
        "actual": true,
        "expected": false
      }
    },
    "accepted_not_outstanding": {
      "caught": 1,
      "witness": {
        "group": "human_mode_gate",
        "case": "accepted",
        "actual": false,
        "expected": true
      }
    },
    "late_timeout_regresses_sent": {
      "caught": 1,
      "witness": {
        "group": "lifecycle",
        "case": [
          "sent",
          "timeout"
        ],
        "actual": "outcome_unknown",
        "expected": "sent"
      }
    },
    "request_equals_cancel": {
      "caught": 3,
      "witness": {
        "group": "lifecycle",
        "case": [
          "dispatching",
          "cancel_request"
        ],
        "actual": "cancelled",
        "expected": "dispatching"
      }
    },
    "timeout_resends": {
      "caught": 3,
      "witness": {
        "group": "lifecycle",
        "case": [
          "dispatching",
          "timeout"
        ],
        "actual": "pending",
        "expected": "outcome_unknown"
      }
    }
  },
  "runtime_tests": false
}
